SELECT tenant_id, consumer_id, event_id, callback_id, payload_hash, status
FROM sys_flow_event_inbox
WHERE tenant_id = #{tenantId} AND consumer_id = #{consumerId}
  AND event_id = #{eventId} AND callback_id = #{callbackId}
FOR UPDATE

mapper.update:
